namespace PZ3D {static class ServerSessionNative {
 static int checks;static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 static void Check(bool v,string text){checks++;if(!v)throw new Exception(text);Console.WriteLine("PASS "+text);}
 static Dictionary<string,object> P(params object[] items){var p=new Dictionary<string,object>();for(int n=0;n<items.Length;n+=2)p.Add((string)items[n],items[n+1]);return p;}
 static void Put(string p,string s){Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllText(p,s,new UTF8Encoding(false));}
 static string[][] Rows(string file,string key){return File.ReadAllLines(file).Where(x=>x.StartsWith(key+"\t")).Select(x=>x.Split('\t').Skip(1).Select(v=>Encoding.UTF8.GetString(Convert.FromBase64String(v))).ToArray()).ToArray();}
 static void Contract(){ModernHostPolicy.ValidateStartupPayload("startupBegin",P("targetKind","server","targetId","server-id","serverComponents","force-local"));Check(true,"strict startup accepts explicit server choice");ModernHostPolicy.ValidateLaunchPayload("profileLaunch",P("startupId",new string('a',32),"kind","server","id","server-id","serverComponents","follow-server"));Check(true,"strict profile launch accepts matching server choice field");foreach(string kind in new[]{"normal","save"}){bool refused=false;try{ModernHostPolicy.ValidateStartupPayload("startupBegin",P("targetKind",kind,"targetId",kind=="normal"?"":"Sandbox/Save","serverComponents","force-local"));}catch{refused=true;}Check(refused,"server choice is rejected for "+kind);}bool bad=false;try{ModernHostPolicy.ValidateStartupPayload("startupBegin",P("targetKind","server","targetId","server-id","serverComponents","allow-all"));}catch{bad=true;}Check(bad,"unknown server mode is rejected");}
 sealed class Fixture {internal string Game,User,Data,Buddy,Root;internal Engine Engine;internal LauncherComponents Components;internal Fixture(string root,bool owned){Root=root;Game=Path.Combine(root,"game");User=Path.Combine(root,"用户");Data=Path.Combine(root,"data");foreach(string file in new[]{"ProjectZomboid64.exe","projectzomboid.jar","jre64/bin/java.exe","jre64/bin/server/jvm.dll","steam_api64.dll","ZNetJNI64.dll","Lighting64.dll"})Put(Path.Combine(Game,file),"isolated; never launch");Put(Path.Combine(Game,"version.txt"),"42.21.0");Put(Path.Combine(Game,"game-version.txt"),"42.21.0");Put(Path.Combine(Game,"ProjectZomboid64.json"),"{\"mainClass\":\"zombie/gameStates/MainScreenState\",\"classpath\":[\"projectzomboid.jar\"],\"vmArgs\":[\"-Xmx2g\"]}");Put(Path.Combine(User,"mods/default.txt"),"VERSION = 1,\nmods\n{\n mod = PlainSingleplayer,\n mod = CustomClient,\n}\nmaps\n{\n}\n");Put(Path.Combine(User,"mods/PlainSingleplayer/42/mod.info"),"id=PlainSingleplayer\n");Put(Path.Combine(User,"mods/CustomClient/42/mod.info"),"id=CustomClient\nrequire=ZombieBuddy\n");Buddy=Path.Combine(User,"mods/ZombieBuddy");Put(Path.Combine(Buddy,"42/mod.info"),"id=ZombieBuddy\n");Directory.CreateDirectory(Path.Combine(Buddy,"libs"));File.Copy(Path.Combine(Environment.CurrentDirectory,"Dependencies/ZombieBuddy-v2.3.4.jar"),Path.Combine(Buddy,"libs/ZombieBuddy.jar"));Engine=new Engine(Game,User,Data,true,null,_=>new System.Diagnostics.Process[0]);if(owned){Engine.BindConfiguration(new LaunchConfigurationProfiles(Data,Game,User).Resolve("launcher"));Components=Engine.OwnedComponents();Components.Select(Buddy,"ZombieBuddy",true,CancellationToken.None);Components.SaveOrdinary(new[]{"PlainSingleplayer","CustomClient"},CancellationToken.None);}else{Put(Path.Combine(Game,"zbNative.dll"),"isolated; never execute");File.Copy(Path.Combine(Buddy,"libs/ZombieBuddy.jar"),Path.Combine(Game,"ZombieBuddy.jar"));Put(Path.Combine(Game,"ProjectZomboid64.json"),"{\"mainClass\":\"zombie/gameStates/MainScreenState\",\"classpath\":[\"projectzomboid.jar\"],\"vmArgs\":[\"-Xmx2g\",\"-agentlib:zbNative\"]}");}}
 }
 static ProfileLaunchRequest Request(string mode){var r=new ProfileLaunchRequest{Kind="server",Host="127.0.0.1",Port=16261,Username="isolated",Cancellation=CancellationToken.None};var field=typeof(ProfileLaunchRequest).GetField("ServerComponents");Check(field!=null,"native launch request owns the server mode");field.SetValue(r,mode);return r;}
 static void Stage(string root,bool owned,string mode){var f=new Fixture(root,owned);byte[] original=File.ReadAllBytes(f.Engine.Mods),config=File.ReadAllBytes(f.Engine.Config);LaunchProfiles.Stage(f.Engine,Request(mode));try{var s=f.Engine.LiveSession;Check(s!=null,"actual "+(owned?"owned":"Steam")+" server stage uses a temporary runtime");Check(Rows(s.Manifest,"server-components").Single()[0]==mode,"mode reaches the hash-bound runtime manifest");Check(s.VmArguments.Any(x=>x.Contains("policy=prompt"))&&!s.VmArguments.Any(x=>x.Contains("deny-new")||x.Contains("allow-all")),"server Buddy uses its native prompt policy");var selected=Rows(s.Manifest,"selected").Select(x=>x[0]).ToArray();Check(!selected.Contains("PlainSingleplayer")&&(mode=="follow-server"?!selected.Contains("CustomClient"):selected.Contains("CustomClient")),"server selection excludes unrelated ordinary Lua and honors all component mode");Check(original.SequenceEqual(File.ReadAllBytes(f.Engine.Mods))&&config.SequenceEqual(File.ReadAllBytes(f.Engine.Config)),"stage preserves current default and launch JSON bytes");var args=LaunchProfiles.BuildStartInfo(f.Engine).Arguments;Check(args.Contains("ozl.live.manifest")&&!args.Contains("policy=deny-new"),"production process command uses temporary server agent and prompt");}finally{LaunchProfiles.Recover(f.Engine,true);}Check(!LaunchProfiles.Pending(f.Engine)&&original.SequenceEqual(File.ReadAllBytes(f.Engine.Mods))&&config.SequenceEqual(File.ReadAllBytes(f.Engine.Config)),"server recovery clears its own files and preserves original settings");}
 static void Attempt(string root){var f=new Fixture(root,true);using(var c=new ModernController(f.Game,f.User,f.Data,true)){var begin=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(c.Execute("startupBegin",P("targetKind","server","targetId","server-choice","serverComponents","force-local"))));string id=(string)begin["startupId"];bool rejected=false;try{c.Execute("profileLaunch",P("startupId",id,"kind","server","id","server-choice","serverComponents","follow-server"));}catch(Exception error){rejected=error.Message.Contains("不一致");}Check(rejected,"native startup reservation rejects changing the captured server mode");try{c.Execute("profileLaunch",P("startupId",id,"kind","server","id","server-choice","serverComponents","force-local"));throw new Exception("actual game entry was allowed in test");}catch(Exception error){Check(error.Message.Contains("测试模式禁止真实游戏"),"same captured mode reaches actual production profile preflight and stops only at test launch boundary");}}var request=Request("force-local");var cancel=new CancellationTokenSource();request.Cancellation=cancel.Token;request.ValidateBeforeStage=()=>cancel.Cancel();bool cancelled=false;try{LaunchProfiles.Stage(f.Engine,request);}catch(OperationCanceledException){cancelled=true;}Check(cancelled&&!LaunchProfiles.Pending(f.Engine)&&!File.Exists(Path.Combine(f.User,"Lua/OrangeLauncherSession.request.txt")),"actual cancellation after staging removes the temporary session before any connection request is published");string runtime=Path.Combine(f.Data,"server-sessions",LaunchProfiles.Key(f.Engine));Check(!Directory.Exists(runtime)||!Directory.Exists(Path.Combine(runtime,"runtime"))||!Directory.EnumerateDirectories(Path.Combine(runtime,"runtime")).Any(),"cancelled server preparation releases all temporary runtime files");}
 static void ActiveOwnedFiles(string root){var f=new Fixture(root,true);new OwnedSupportInstallations(f.Components).Enable("ZombieBuddy",f.Buddy,CancellationToken.None);string installed=f.Components.Installations(CancellationToken.None).Single(row=>row.Id=="ZombieBuddy").SourceRoot;LaunchProfiles.Stage(f.Engine,Request("force-local"));try{using(var c=new ModernController(f.Game,f.User,f.Data,true)){bool blocked=false;try{c.Execute("configurationRequest",P("id","launcher","action","componentsAction","payload",P("component","buddy","operation","uninstall","confirmed",true)));}catch(IOException error){blocked=error.Message.Contains("启动会话");}Check(blocked&&File.Exists(Path.Combine(installed,"libs/ZombieBuddy.jar")),"owned server session protects actual managed source files from uninstall while in use");c.Execute("configurationRequest",P("id","launcher","action","componentsAction","payload",P("component","buddy","operation","disable","confirmed",true)));Check(File.Exists(Path.Combine(installed,"libs/ZombieBuddy.jar"))&&!f.Components.Installations(CancellationToken.None).Single().Enabled,"owned server session still permits selection-only disable and preserves runtime files");var read=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(c.Execute("configurationRequest",P("id","launcher","action","status","payload",P()))));Check(read.ContainsKey("data"),"active owned server session does not lock unrelated read-only status");var profiles=new LaunchConfigurationProfiles(f.Data,f.Game,f.User);var other=profiles.Create("other support owner",profiles.Resolve("launcher").VersionId,new string[0]);var service=new LauncherComponents(other.Context,new Version(42,21));string otherCopy=new OwnedSupportInstallations(service).Enable("ZombieBuddy",f.Buddy,CancellationToken.None);c.Execute("configurationRequest",P("id",other.Id,"action","componentsAction","payload",P("component","buddy","operation","uninstall","confirmed",true)));Check(!Directory.Exists(otherCopy)&&File.Exists(Path.Combine(installed,"libs/ZombieBuddy.jar")),"another configuration can uninstall its own copy during the active server session");}}finally{LaunchProfiles.Recover(f.Engine,true);}}
 static void CaptureRevision(string root){var f=new Fixture(root,true);string endpoint="127.0.0.1:16261",catalog=Path.Combine(f.Data,"server-workshop",DlssInstaller.Hash(Encoding.UTF8.GetBytes(endpoint))+".json"),stamp=new string('b',32);LauncherNativeState.Write(catalog,new ServerWorkshopManifest{endpoint=endpoint,stamp=stamp,source="imported",capturedUtc=DateTime.UtcNow.ToString("o"),ids=new[]{"111"}});LaunchProfiles.Stage(f.Engine,Request("follow-server"));var record=LaunchProfiles.ServerSession(f.Engine,File.ReadAllLines(Path.Combine(f.User,"Lua/OrangeLauncherSession.request.txt"))[1]);Check(record.CaptureRevision==stamp,"temporary server session preserves existing Workshop capture revision authority");Put(Path.Combine(f.User,"Lua/OrangeLauncherWorkshop.txt"),"ORANGE_WORKSHOP_1\n"+record.Nonce+"\n"+endpoint+"\n1\n222\nEND\n");LaunchProfiles.Recover(f.Engine,true);var current=Json.Deserialize<ServerWorkshopManifest>(File.ReadAllText(catalog));Check(current.ids.SequenceEqual(new[]{"222"}),"real connection receipt can refresh the previously recorded Workshop list during recovery");}
 static void RuntimeProperties(string root){var f=new Fixture(root,false);Put(f.Engine.Config,"{\"mainClass\":\"zombie/gameStates/MainScreenState\",\"classpath\":[\"projectzomboid.jar\"],\"vmArgs\":[\"-Xmx2g\",\"-agentlib:zbNative\",\"-Dzb.policy=allow-all\",\"-Dzb.policy=deny-new\",\"-Dzb.frontend=console\",\"-Dzb.patches_jar=foreign.jar\",\"-Dzombie_buddy.policy=allow-all\",\"-Dunrelated.setting=keep\"]}");byte[] before=File.ReadAllBytes(f.Engine.Config);LaunchProfiles.Stage(f.Engine,Request("follow-server"));try{string args=LaunchProfiles.BuildStartInfo(f.Engine).Arguments;Check(!args.Contains("allow-all")&&!args.Contains("deny-new")&&!args.Contains("frontend=console")&&!args.Contains("foreign.jar"),"server command strips inherited Buddy policy/frontend/patch overrides that could bypass native approval");Check(args.Contains("policy=prompt")&&args.Contains("-Dunrelated.setting=keep")&&before.SequenceEqual(File.ReadAllBytes(f.Engine.Config)),"runtime policy override preserves unrelated options and original Steam JSON bytes");}finally{LaunchProfiles.Recover(f.Engine,true);}}
 static void SortWarning(string root){var f=new Fixture(root,true);Put(Path.Combine(f.User,"mods/CycleA/42/mod.info"),"id=CycleA\nrequire=ZombieBuddy\nloadAfter=CycleB\n");Put(Path.Combine(f.User,"mods/CycleB/42/mod.info"),"id=CycleB\nrequire=ZombieBuddy\nloadAfter=CycleA\n");f.Components.SaveOrdinary(new[]{"PlainSingleplayer","CycleB","CycleA"},CancellationToken.None);var report=LaunchPreflight.CheckLaunch(f.Engine,false,false,"server",null,true,"force-local");Check(report.canLaunch&&report.items.Any(item=>item.status=="warning"),"component sorting cycle is a visible warning and never blocks server connection");LaunchProfiles.Stage(f.Engine,Request("force-local"));try{var order=Rows(f.Engine.LiveSession.Manifest,"order").Select(row=>row[0]).Where(id=>id.StartsWith("Cycle")).ToArray();Check(order.SequenceEqual(new[]{"CycleB","CycleA"}),"cyclic component order retains the original selected sequence without rewriting the ordinary list");}finally{LaunchProfiles.Recover(f.Engine,true);}}
 static void LegacyServer(string root){var f=new Fixture(root,false);File.Delete(Path.Combine(f.Game,"projectzomboid.jar"));using(var zip=System.IO.Compression.ZipFile.Open(Path.Combine(f.Game,"projectzomboid.jar"),System.IO.Compression.ZipArchiveMode.Create))foreach(string name in new[]{"Core.class","GameVersion.class"})using(var stream=zip.CreateEntry("zombie/core/"+name).Open()){byte[] bytes=File.ReadAllBytes(Path.Combine(Environment.GetEnvironmentVariable("OZL_SERVER_VERSION_CLASSES"),"zombie/core/"+name));stream.Write(bytes,0,bytes.Length);}Check(GameVersionProbe.Read(f.Game).Major==41,"production game-version reader verifies compiled B41 fixture bytecode");Put(Path.Combine(f.Game,"version.txt"),"41.78.16");Put(Path.Combine(f.Game,"game-version.txt"),"41.78.16");Put(f.Engine.Config,"{\"mainClass\":\"zombie/gameStates/MainScreenState\",\"classpath\":[\".\"],\"vmArgs\":[\"-Xmx2g\"]}");byte[] defaults=File.ReadAllBytes(f.Engine.Mods),config=File.ReadAllBytes(f.Engine.Config);foreach(string mode in new[]{"follow-server","force-local"}){var report=LaunchPreflight.CheckLaunch(f.Engine,false,false,"server",null,true,mode);Check(report.canLaunch&&report.items.SelectMany(item=>item.details).Any(text=>text.Contains("Buddy")),"B41 Steam server keeps its existing non-Java connection path with an honest loader warning");LaunchProfiles.Stage(f.Engine,Request(mode));try{Check(File.Exists(Path.Combine(f.User,"mods/OrangeLauncherSession/mod.info"))&&f.Engine.LiveSession==null,"B41 uses the existing legacy bridge instead of claiming B42 Live support");Check(File.ReadAllBytes(f.Engine.Config).SequenceEqual(config),"B41 server preparation preserves launch JSON bytes");}finally{LaunchProfiles.Recover(f.Engine,true);}Check(File.ReadAllBytes(f.Engine.Mods).SequenceEqual(defaults)&&!LaunchProfiles.Pending(f.Engine),"B41 temporary list and bridge recover to exact original bytes");}}
 static void LegacyComponents(string root){var f=new Fixture(root,true);string component=Path.Combine(f.User,"mods/OldLuaAdapter");Put(Path.Combine(component,"42/mod.info"),"id=OldLuaAdapter\n");string statePath=Path.Combine(f.Engine.OwnedConfiguration.ComponentsDirectory,"selection.json");var state=Json.Deserialize<LauncherComponents.State>(File.ReadAllText(statePath));state.Selections.Add(new LauncherComponents.Selection{Id="OldLuaAdapter",SourceRoot=Path.GetFullPath(component),Enabled=true});File.WriteAllText(statePath,Json.Serialize(state),new UTF8Encoding(false));f.Components.Select(Path.Combine(f.User,"mods/PlainSingleplayer"),"PlainSingleplayer",true,CancellationToken.None);byte[] stateBytes=File.ReadAllBytes(statePath),ordinary=File.ReadAllBytes(f.Engine.Mods);Put(Path.Combine(f.User,"mods/UnrelatedDuplicate/42/mod.info"),"id=PlainSingleplayer\n");LaunchProfiles.Stage(f.Engine,Request("force-local"));try{var rows=Rows(f.Engine.LiveSession.Manifest,"selected");Check(rows.Any(row=>row[0]=="OldLuaAdapter")&&!rows.Any(row=>row[0]=="PlainSingleplayer"),"force-local retains old enabled component receipts without treating ordinary source pins as components");Check(stateBytes.SequenceEqual(File.ReadAllBytes(statePath))&&ordinary.SequenceEqual(File.ReadAllBytes(f.Engine.Mods)),"legacy component retention is a read-only projection preserving exact receipts and ordinary bytes");}finally{LaunchProfiles.Recover(f.Engine,true);}}
