 static void PendingJava(string root){var f=new Fixture(root,true);bool preflightCancelled=false;try{LaunchPreflight.CheckLaunch(f.Engine,false,false,"server",null,true,"force-local",new CancellationToken(true));}catch(OperationCanceledException){preflightCancelled=true;}Check(preflightCancelled,"server preflight honors cancellation as cancellation rather than an unrelated launch error");string mod=Path.Combine(f.User,"mods/CustomClient/42");Put(Path.Combine(mod,"mod.info"),"id=CustomClient\nrequire=ZombieBuddy\njavaJarFile=payload.jar\njavaPkgName=fixture.client\n");using(var zip=System.IO.Compression.ZipFile.Open(Path.Combine(mod,"payload.jar"),System.IO.Compression.ZipArchiveMode.Create))using(var writer=new StreamWriter(zip.CreateEntry("fixture/client/Marker.class").Open()))writer.Write("isolated sentinel");foreach(string mode in new[]{"follow-server","force-local"}){var report=LaunchPreflight.CheckLaunch(f.Engine,false,false,"server",null,true,mode);Check(report.canLaunch,"pending local Java does not preempt native Buddy server approval in "+mode);LaunchProfiles.Stage(f.Engine,Request(mode));try{Check(Rows(f.Engine.LiveSession.Manifest,"jar").Length==0,"server manifest has no startup-fixed Java allowlist");string config=File.ReadAllText(Path.Combine(f.Engine.LiveSession.Directory,"buddy/config.json"));Check(config.Contains("\"preload_mods\":{}")&&config.Contains("\"trusted_authors\":[]"),"server session does not preload Java or trust authors before native approval");}finally{LaunchProfiles.Recover(f.Engine,true);}}var normal=LaunchPreflight.CheckLaunch(f.Engine,false,false,"normal",null,true);Check(!normal.canLaunch,"single-player still requires its exact current Java approval");}
 static void NamedVanilla(string root){var f=new Fixture(root,true);var profiles=new LaunchConfigurationProfiles(f.Data,f.Game,f.User);var named=profiles.Create("server named",profiles.Resolve("launcher").VersionId,new[]{"PlainSingleplayer","CustomClient"});var namedEngine=new Engine(named.Context.Game,named.Context.User,f.Data,true,null,_=>new System.Diagnostics.Process[0]);namedEngine.BindConfiguration(named);namedEngine.OwnedComponents().Select(f.Buddy,"ZombieBuddy",true,CancellationToken.None);byte[] current=File.ReadAllBytes(f.Engine.Mods);LaunchProfiles.Stage(namedEngine,Request("force-local"));try{Check(Rows(namedEngine.LiveSession.Manifest,"selected").Any(row=>row[0]=="CustomClient"),"named configuration retains its own custom Buddy-dependent component");Check(SaveProfiles.DefaultMods(File.ReadAllBytes(Path.Combine(namedEngine.LiveSession.Directory,"mods/default.txt"))).SequenceEqual(new[]{"OrangeLauncherSession"}),"menu defaults defer every local component until actual server load");Check(current.SequenceEqual(File.ReadAllBytes(f.Engine.Mods)),"named server preparation does not alter builtin membership");}finally{LaunchProfiles.Recover(namedEngine,true);}var vanilla=new Engine(f.Game,f.User,f.Data,true,null,_=>new System.Diagnostics.Process[0]);vanilla.BindConfiguration(profiles.Resolve("vanilla"));var report=LaunchPreflight.CheckLaunch(vanilla,false,false,"server",null,true,"force-local");Check(report.canLaunch&&report.items.SelectMany(item=>item.details).Any(text=>text.Contains("Buddy")),"vanilla server preflight stays available and honestly warns no Java loader");LaunchProfiles.Stage(vanilla,Request("force-local"));try{Check(!vanilla.LiveSession.VmArguments.Any(arg=>arg.Contains("policy="))&&!Rows(vanilla.LiveSession.Manifest,"selected").Any(row=>row[0]!="OrangeLauncherSession"),"vanilla keeps zero optional local components while allowing native server discovery");}finally{LaunchProfiles.Recover(vanilla,true);}}
 static void Frozen(string root){var f=new Fixture(root,true);Put(Path.Combine(f.User,"Saves/Sandbox/Test/mods.txt"),"mods\n{\n mod = PlainSingleplayer,\n mod = CustomClient,\n}\nmaps\n{\n}\n");var service=new SaveEnvironments(f.Engine);var plan=service.Preview("Sandbox/Test");Check(plan.ready,"actual snapshot plan with a client component is ready");var saved=service.Create("Sandbox/Test",Path.Combine(root,"中文快照"),"server overlay",plan.stamp,CancellationToken.None,null,row=>SaveEnvironmentRuntime.Prepare(f.Engine,row));var engine=new Engine(saved.GamePath,saved.UserPath,f.Data,true,null,_=>new System.Diagnostics.Process[0]);engine.BindConfiguration(new LaunchConfigurationResolution{Id="snapshot:"+saved.Id,Kind="frozen",Available=true,Snapshot=saved});string properties=Path.Combine(saved.GamePath,"OrangeLauncherRuntime/environment/environment.properties");var original=new Dictionary<string,byte[]>();foreach(string file in new[]{engine.Mods,engine.Config,properties,saved.ManifestPath,Path.Combine(saved.RootPath,"runtime/mods/loaded.txt")}.Where(File.Exists))original[file]=File.ReadAllBytes(file);foreach(string mode in new[]{"follow-server","force-local"}){var report=LaunchPreflight.CheckLaunch(engine,false,false,"server",null,true,mode);Check(report.canLaunch,"explicit snapshot server preflight uses connection semantics: "+Json.Serialize(report));LaunchProfiles.Stage(engine,Request(mode));try{Check(original.All(pair=>pair.Value.SequenceEqual(File.ReadAllBytes(pair.Key))),"snapshot server stage preserves frozen original files and execution rules");var selected=Rows(engine.LiveSession.Manifest,"selected");Check(selected.All(row=>row[0]!="PlainSingleplayer")&&(mode=="follow-server"?!selected.Any(row=>row[0]=="CustomClient"):selected.Any(row=>row[0]=="CustomClient"&&row[1].StartsWith(saved.RootPath))),"snapshot force uses copied client roots only; follow excludes them");string args=LaunchProfiles.BuildStartInfo(engine).Arguments;Check(args.Contains("policy=prompt")&&!args